import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import vm from 'node:vm';import {knowledgeManifest,REDA_CLINICAL_KNOWLEDGE_VERSION} from '../../reda-2/clinical-knowledge.mjs';
test('all eight core blueprints now expose progression and regression graphs',()=>{const core={blueprints:{knee_pf:{},knee_oa:{},knee_tendon:{},shoulder_load:{},hip_gtps:{},achilles:{},neck:{},lumbar:{}}};const ctx={RedaClinical:core,RedaData:{exercises:[]}};vm.createContext(ctx);vm.runInContext(fs.readFileSync(new URL('../../reda-2/clinical-library-v3.js',import.meta.url),'utf8'),ctx);const m=knowledgeManifest(core.blueprints);assert.equal(m.length,8);assert.ok(m.every(x=>x.nodes>=3&&x.hasRegression));assert.match(REDA_CLINICAL_KNOWLEDGE_VERSION,/^2026\./)});
